def transform(grid):
    """Extend each colored plus along its four arms until another marker."""
    h, w = len(grid), len(grid[0])
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    hollow_cols = {c for r in range(1, h - 1) for c in range(1, w - 1)
                   if grid[r][c] == 0 and grid[r-1][c] == 3
                   and grid[r+1][c] == 3 and grid[r][c-1] == 3
                   and grid[r][c+1] == 3}
    horizontal, vertical = {}, {}
    for r, c, color in centers:
        for dr, dc, dest in ((0, -1, horizontal), (0, 1, horizontal),
                             (-1, 0, vertical), (1, 0, vertical)):
            y, x = r + dr, c + dc
            if not (0 <= y < h and 0 <= x < w):
                continue
            # Skip the source plus's own adjacent 3 arm.
            if grid[y][x] == 3:
                y, x = y + dr, x + dc
            while 0 <= y < h and 0 <= x < w:
                if grid[y][x] != 0:
                    break
                if dest is vertical or x not in hollow_cols:
                    dest[(y, x)] = color
                y, x = y + dr, x + dc
    out = [row[:] for row in grid]
    for (r, c), color in horizontal.items():
        out[r][c] = color
    for (r, c), color in vertical.items():
        out[r][c] = color
    return out
